package com.spendwise.api.service;

import com.spendwise.api.dto.FinanceDtos;
import com.spendwise.api.model.*;
import com.spendwise.api.repository.*;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.time.YearMonth;
import java.util.List;

@Service
public class FinanceService {
    private final AppUserRepository users; private final UserProfileRepository profiles; private final IncomeRepository incomes; private final ExpenseRepository expenses;
    private final SavingsGoalRepository goals; private final CreditCardRepository cards; private final EmiRecordRepository emis; private final PurchaseSimulationRepository simulations;
    private final ExpenseCategoryRepository categories; private final BudgetRepository budgets; private final CreditTransactionRepository cardTransactions; private final NotificationRepository notifications;
    public FinanceService(AppUserRepository users,UserProfileRepository profiles,IncomeRepository incomes,ExpenseRepository expenses,SavingsGoalRepository goals,CreditCardRepository cards,EmiRecordRepository emis,PurchaseSimulationRepository simulations,ExpenseCategoryRepository categories,BudgetRepository budgets,CreditTransactionRepository cardTransactions,NotificationRepository notifications) {
        this.users=users;this.profiles=profiles;this.incomes=incomes;this.expenses=expenses;this.goals=goals;this.cards=cards;this.emis=emis;this.simulations=simulations;this.categories=categories;this.budgets=budgets;this.cardTransactions=cardTransactions;this.notifications=notifications;
    }
    private AppUser user(String email){return users.findByEmail(email.toLowerCase()).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Account not found"));}
    private UserProfile profile(AppUser u){return profiles.findByUserId(u.getId()).orElseGet(()->profiles.save(new UserProfile(u)));}
    @Transactional(readOnly=true) public FinanceDtos.ProfileView getProfile(String email){var p=profiles.findByUserId(user(email).getId()).orElse(null);return p==null?new FinanceDtos.ProfileView(BigDecimal.ZERO,BigDecimal.ZERO,BigDecimal.ZERO,BigDecimal.ZERO,BigDecimal.ZERO,null):profileView(p);}
    @Transactional public FinanceDtos.ProfileView updateProfile(String email,FinanceDtos.ProfileRequest r){var p=profile(user(email));p.update(r.availableBalance(),r.monthlySalary(),r.essentialExpenses(),r.emergencySavings(),r.creditObligations());return profileView(p);}
    private FinanceDtos.ProfileView profileView(UserProfile p){return new FinanceDtos.ProfileView(p.getAvailableBalance(),p.getMonthlySalary(),p.getEssentialExpenses(),p.getEmergencySavings(),p.getCreditObligations(),p.getUpdatedAt());}
    @Transactional(readOnly=true) public FinanceDtos.DashboardView dashboard(String email){
        AppUser u=user(email); YearMonth ym=YearMonth.now();
        BigDecimal in=incomes.sumForPeriod(u.getId(),ym.atDay(1),ym.atEndOfMonth()),out=expenses.sumForPeriod(u.getId(),ym.atDay(1),ym.atEndOfMonth());
        UserProfile p=profiles.findByUserId(u.getId()).orElse(new UserProfile(u)); if(in.signum()==0)in=p.getMonthlySalary(); if(out.signum()==0)out=p.getEssentialExpenses();
        BigDecimal saved=in.subtract(out),rate=in.signum()>0?saved.multiply(BigDecimal.valueOf(100)).divide(in,1,RoundingMode.HALF_UP):BigDecimal.ZERO;
        List<FinanceDtos.TrendPoint> trend=java.util.stream.IntStream.range(0,12).mapToObj(i->{YearMonth m=ym.minusMonths(11-i);BigDecimal monthIncome=incomes.sumForPeriod(u.getId(),m.atDay(1),m.atEndOfMonth()),monthExpenses=expenses.sumForPeriod(u.getId(),m.atDay(1),m.atEndOfMonth());return new FinanceDtos.TrendPoint(m.getMonth().getDisplayName(java.time.format.TextStyle.SHORT,java.util.Locale.ENGLISH),monthIncome,monthExpenses,monthIncome.subtract(monthExpenses));}).toList();
        List<String> colors=List.of("#10B981","#22D3EE","#8B7CF6","#F3A95F","#66736C");
        List<Object[]> categoryRows=expenses.categoryTotals(u.getId(),ym.atDay(1),ym.atEndOfMonth());
        List<FinanceDtos.CategorySpend> breakdown=java.util.stream.IntStream.range(0,Math.min(5,categoryRows.size())).mapToObj(i->{Object[] row=categoryRows.get(i);return new FinanceDtos.CategorySpend((String)row[0],(BigDecimal)row[1],colors.get(i));}).toList();
        return new FinanceDtos.DashboardView(profileView(p),in,out,saved,rate,emis.sumMonthlyPayments(u.getId()),cards.sumOutstanding(u.getId()),incomes.countByUserId(u.getId()),expenses.countByUserId(u.getId()),trend,breakdown);
    }
    @Transactional(readOnly=true) public List<FinanceDtos.IncomeView> incomes(String e){return incomes.findAllByUserIdOrderByDateDesc(user(e).getId()).stream().map(i->new FinanceDtos.IncomeView(i.getId(),i.getSource(),i.getAmount(),i.getDate(),i.getNote())).toList();}
    @Transactional public FinanceDtos.IncomeView addIncome(String e,FinanceDtos.IncomeRequest r){var i=incomes.save(new Income(user(e),r.source().trim(),r.amount(),r.date(),r.note()));return new FinanceDtos.IncomeView(i.getId(),i.getSource(),i.getAmount(),i.getDate(),i.getNote());}
    @Transactional(readOnly=true) public List<FinanceDtos.ExpenseView> expenses(String e){return expenses.findAllByUserIdOrderByDateDesc(user(e).getId()).stream().map(this::expenseView).toList();}
    private ExpenseCategory category(AppUser user,String name){return categories.findByUserIdAndNameIgnoreCase(user.getId(),name.trim()).orElseGet(()->categories.save(new ExpenseCategory(user,name.trim(),"#10B981")));}
    @Transactional public FinanceDtos.ExpenseView addExpense(String e,FinanceDtos.ExpenseRequest r){AppUser u=user(e);return expenseView(expenses.save(new Expense(u,r.description().trim(),category(u,r.category()),r.amount(),r.date())));}
    @Transactional public FinanceDtos.ExpenseView updateExpense(String e,Long id,FinanceDtos.ExpenseRequest r){AppUser u=user(e);var x=expenses.findByIdAndUserId(id,u.getId()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Expense not found"));x.update(r.description().trim(),category(u,r.category()),r.amount(),r.date());return expenseView(x);}
    @Transactional public void deleteExpense(String e,Long id){expenses.delete(expenses.findByIdAndUserId(id,user(e).getId()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Expense not found")));}
    private FinanceDtos.ExpenseView expenseView(Expense x){return new FinanceDtos.ExpenseView(x.getId(),x.getDescription(),x.getCategory(),x.getAmount(),x.getDate());}
    @Transactional(readOnly=true) public List<FinanceDtos.GoalView> goals(String e){return goals.findAllByUserIdOrderByIdDesc(user(e).getId()).stream().map(this::goalView).toList();}
    @Transactional public FinanceDtos.GoalView addGoal(String e,FinanceDtos.GoalRequest r){return goalView(goals.save(new SavingsGoal(user(e),r.name().trim(),r.targetAmount(),r.savedAmount(),r.targetDate())));}
    @Transactional public FinanceDtos.GoalView updateGoal(String e,Long id,FinanceDtos.GoalRequest r){var g=goals.findByIdAndUserId(id,user(e).getId()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Goal not found"));g.update(r.name().trim(),r.targetAmount(),r.savedAmount(),r.targetDate());return goalView(g);}
    @Transactional public void deleteGoal(String e,Long id){goals.delete(goals.findByIdAndUserId(id,user(e).getId()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Goal not found")));}
    private FinanceDtos.GoalView goalView(SavingsGoal g){return new FinanceDtos.GoalView(g.getId(),g.getName(),g.getTargetAmount(),g.getSavedAmount(),g.getTargetDate());}
    @Transactional(readOnly=true) public List<FinanceDtos.CardView> cards(String e){return cards.findAllByUserIdOrderByIdDesc(user(e).getId()).stream().map(this::cardView).toList();}
    @Transactional public FinanceDtos.CardView addCard(String e,FinanceDtos.CardRequest r){if(r.outstanding().compareTo(r.creditLimit())>0)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Outstanding balance cannot exceed the card limit");AppUser owner=user(e);var card=cards.save(new CreditCardAccount(owner,r.name().trim(),r.lastFour(),r.creditLimit(),r.outstanding(),r.dueDate()));if(r.dueDate()!=null)notifications.save(new AppNotification(owner,"Credit card payment due",r.name().trim()+" payment is due on "+r.dueDate()+"."));return cardView(card);}
    private FinanceDtos.CardView cardView(CreditCardAccount c){BigDecimal avail=c.getCreditLimit().subtract(c.getOutstanding()).max(BigDecimal.ZERO),pct=c.getCreditLimit().signum()==0?BigDecimal.ZERO:c.getOutstanding().multiply(BigDecimal.valueOf(100)).divide(c.getCreditLimit(),1,RoundingMode.HALF_UP);return new FinanceDtos.CardView(c.getId(),c.getName(),c.getLastFour(),c.getCreditLimit(),c.getOutstanding(),avail,pct,c.getDueDate());}
    @Transactional(readOnly=true) public List<FinanceDtos.EmiView> emis(String e){return emis.findAllByUserIdOrderByNextPaymentDateAsc(user(e).getId()).stream().map(this::emiView).toList();}
    @Transactional public FinanceDtos.EmiView addEmi(String e,FinanceDtos.EmiRequest r){if(r.downPayment().compareTo(r.principal())>0)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Down payment cannot exceed purchase price");AppUser owner=user(e);var calc=calculate(r.principal(),r.downPayment(),r.annualRate(),r.termMonths());var record=emis.save(new EmiRecord(owner,r.label().trim(),r.principal(),r.downPayment(),r.annualRate(),r.termMonths(),calc.monthlyPayment(),r.nextPaymentDate()));if(r.nextPaymentDate()!=null)notifications.save(new AppNotification(owner,"EMI payment scheduled","Next payment for "+r.label().trim()+" is due on "+r.nextPaymentDate()+"."));return emiView(record);}
    private FinanceDtos.EmiView emiView(EmiRecord x){return new FinanceDtos.EmiView(x.getId(),x.getLabel(),x.getPrincipal(),x.getDownPayment(),x.getAnnualRate(),x.getTermMonths(),x.getMonthlyPayment(),x.getNextPaymentDate());}
    public FinanceDtos.EmiCalculationResponse calculateEmi(FinanceDtos.EmiCalculationRequest r){return calculate(r.principal(),r.downPayment(),r.annualRate(),r.termMonths());}
    private FinanceDtos.EmiCalculationResponse calculate(BigDecimal price,BigDecimal down,BigDecimal annual,Integer months){if(down.compareTo(price)>0)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Down payment cannot exceed purchase price");BigDecimal principal=price.subtract(down),rate=annual.divide(BigDecimal.valueOf(1200),12,RoundingMode.HALF_UP),payment;if(rate.signum()==0)payment=principal.divide(BigDecimal.valueOf(months),2,RoundingMode.HALF_UP);else{double r=rate.doubleValue(),f=Math.pow(1+r,months);payment=principal.multiply(BigDecimal.valueOf(r*f/(f-1))).setScale(2,RoundingMode.HALF_UP);}BigDecimal total=payment.multiply(BigDecimal.valueOf(months)).setScale(2,RoundingMode.HALF_UP);return new FinanceDtos.EmiCalculationResponse(principal,payment,total.subtract(principal).max(BigDecimal.ZERO),total,months);}
    @Transactional public FinanceDtos.PurchaseResponse assess(FinanceDtos.PurchaseRequest r){BigDecimal surplus=r.monthlyIncome().subtract(r.monthlyExpenses()).subtract(r.existingEmi()).subtract(r.creditObligations()),projected=r.currentBalance().add(surplus.multiply(BigDecimal.valueOf(r.monthsUntil()))),after=projected.subtract(r.price()),safety=r.monthlyExpenses().multiply(BigDecimal.valueOf(3)),remaining=r.emergencySavings().add(after).max(BigDecimal.ZERO),cover=r.monthlyExpenses().signum()>0?remaining.divide(r.monthlyExpenses(),1,RoundingMode.HALF_UP):(remaining.signum()>0?BigDecimal.valueOf(99):BigDecimal.ZERO);Integer recovery=surplus.signum()>0?r.price().divide(surplus,0,RoundingMode.CEILING).intValue():null;int score=after.signum()>=0?30:0;if(remaining.compareTo(safety)>=0)score+=35;else if(safety.signum()>0)score+=BigDecimal.valueOf(35).multiply(remaining).divide(safety,0,RoundingMode.HALF_UP).intValue();if(surplus.signum()>0)score+=20;if(surplus.compareTo(r.price().divide(BigDecimal.valueOf(3),2,RoundingMode.HALF_UP))>=0)score+=15;score=Math.min(100,score);String verdict=after.signum()<0||surplus.signum()<=0?"Not recommended":score>=75?"Affordable":"Risky";String text=verdict.equals("Affordable")?"After this purchase, your cash and dedicated emergency savings still cover at least three months of expenses. Your monthly surplus can rebuild the purchase amount in about "+recovery+" month"+(recovery==1?".":"s."):verdict.equals("Risky")?"You can cover the price, but it would leave about "+cover+" months of expenses in reserve. Consider waiting or choosing a lower price.":surplus.signum()<=0?"Your current monthly commitments use all of your income. Adding this purchase could increase financial pressure.":"This purchase is about "+after.abs()+" more than your projected cash at the purchase date. Saving first would reduce the risk.";return new FinanceDtos.PurchaseResponse(surplus,projected,after,safety,cover,recovery,score,verdict,text);}
    @Transactional(readOnly=true) public List<FinanceDtos.SimulationView> simulations(String e){return simulations.findAllByUserIdOrderByCreatedAtDesc(user(e).getId()).stream().map(s->new FinanceDtos.SimulationView(s.getId(),s.getProduct(),s.getPrice(),s.getProjectedCash(),s.getCashAfterPurchase(),s.getScore(),s.getRecommendation(),s.getCreatedAt())).toList();}
    @Transactional public FinanceDtos.SimulationView saveSimulation(String e,FinanceDtos.PurchaseRequest r){var a=assess(r);var s=simulations.save(new PurchaseSimulation(user(e),r.product().trim(),r.price(),a.projectedCash(),a.cashAfterPurchase(),a.score(),a.recommendation()));return new FinanceDtos.SimulationView(s.getId(),s.getProduct(),s.getPrice(),s.getProjectedCash(),s.getCashAfterPurchase(),s.getScore(),s.getRecommendation(),s.getCreatedAt());}
    @Transactional(readOnly=true) public List<FinanceDtos.CategoryView> categories(String e){return categories.findAllByUserIdOrderByNameAsc(user(e).getId()).stream().map(c->new FinanceDtos.CategoryView(c.getId(),c.getName(),c.getColor())).toList();}
    @Transactional public FinanceDtos.CategoryView addCategory(String e,FinanceDtos.CategoryRequest r){var c=categories.save(new ExpenseCategory(user(e),r.name().trim(),r.color()==null?"#10B981":r.color()));return new FinanceDtos.CategoryView(c.getId(),c.getName(),c.getColor());}
    @Transactional(readOnly=true) public List<FinanceDtos.BudgetView> budgets(String e,Integer year,Integer month){YearMonth now=YearMonth.now();int selectedYear=year==null?now.getYear():year,selectedMonth=month==null?now.getMonthValue():month;return budgets.findAllByUserIdAndYearAndMonthOrderByIdAsc(user(e).getId(),selectedYear,selectedMonth).stream().map(b->new FinanceDtos.BudgetView(b.getId(),b.getCategoryId(),b.getCategoryName(),b.getYear(),b.getMonth(),b.getLimitAmount())).toList();}
    @Transactional public FinanceDtos.BudgetView addBudget(String e,FinanceDtos.BudgetRequest r){AppUser u=user(e);var c=categories.findByIdAndUserId(r.categoryId(),u.getId()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Expense category not found"));YearMonth period=YearMonth.of(r.year(),r.month());var existing=budgets.findAllByUserIdAndYearAndMonthOrderByIdAsc(u.getId(),r.year(),r.month()).stream().filter(b->b.getCategoryId().equals(c.getId())).findFirst();var b=existing.orElseGet(()->new Budget(u,c,period,r.limitAmount()));b.updateLimitAmount(r.limitAmount());b=budgets.save(b);return new FinanceDtos.BudgetView(b.getId(),c.getId(),b.getCategoryName(),b.getYear(),b.getMonth(),b.getLimitAmount());}
    @Transactional(readOnly=true) public List<FinanceDtos.CardTransactionView> cardTransactions(String e,Long id){var card=cards.findByIdAndUserId(id,user(e).getId()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Card not found"));return cardTransactions.findAllByCardIdOrderByDateDesc(card.getId()).stream().map(t->new FinanceDtos.CardTransactionView(t.getId(),id,t.getDescription(),t.getAmount(),t.getDate())).toList();}
    @Transactional public FinanceDtos.CardTransactionView addCardTransaction(String e,Long id,FinanceDtos.CardTransactionRequest r){var card=cards.findByIdAndUserId(id,user(e).getId()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Card not found"));if(card.getOutstanding().add(r.amount()).compareTo(card.getCreditLimit())>0)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Transaction would exceed the card limit");card.addOutstanding(r.amount());var t=cardTransactions.save(new CreditTransaction(card,r.description().trim(),r.amount(),r.date()));return new FinanceDtos.CardTransactionView(t.getId(),id,t.getDescription(),t.getAmount(),t.getDate());}
    @Transactional(readOnly=true) public List<FinanceDtos.NotificationView> notifications(String e){return notifications.findAllByUserIdOrderByCreatedAtDesc(user(e).getId()).stream().map(n->new FinanceDtos.NotificationView(n.getId(),n.getTitle(),n.getMessage(),n.isRead(),n.getCreatedAt())).toList();}
    @Transactional public FinanceDtos.NotificationView markNotificationRead(String e,Long id){var n=notifications.findByIdAndUserId(id,user(e).getId()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Notification not found"));n.markRead();return new FinanceDtos.NotificationView(n.getId(),n.getTitle(),n.getMessage(),n.isRead(),n.getCreatedAt());}
}
